using LUMAR_ERP_API_V2.DTOs.Settings;using LUMAR_ERP_API_V2.Repositories;namespace LUMAR_ERP_API_V2.Services;public sealed class SettingsService(ISettingsRepository r):ISettingsService{private static readonly IReadOnlyDictionary<string,string> SupportedCurrencies=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){["YER"]="الريال اليمني",["SAR"]="الريال السعودي",["USD"]="الدولار الأمريكي",["EGP"]="الجنيه المصري",["QAR"]="الريال القطري",["OMR"]="الريال العماني",["AED"]="الدرهم الإماراتي",["KWD"]="الدينار الكويتي",["IQD"]="الدينار العراقي",["SDG"]="الجنيه السوداني"};public Task<IReadOnlyList<SystemSettingListDto>> GetAllAsync(CancellationToken c)=>r.GetAllAsync(c);public Task<SystemSettingDetailsDto?> GetByIdAsync(int i,CancellationToken c)=>r.GetByIdAsync(i,c);public Task<SystemSettingDetailsDto?> GetByKeyAsync(string k,CancellationToken c)=>r.GetByKeyAsync(k,c);public Task<IReadOnlyList<SettingCategoryDto>> GetCategoriesAsync(CancellationToken c)=>r.GetCategoriesAsync(c);public Task<IReadOnlyList<SystemSettingListDto>> GetByCategoryAsync(string category,CancellationToken c)=>r.GetByCategoryAsync(category,c);public Task<ProductionRoutesConfigDto> GetProductionRoutesConfigAsync(CancellationToken c)=>r.GetProductionRoutesConfigAsync(c);public Task<IReadOnlyList<string>> GetProductionRoutePieceTypesAsync(CancellationToken c)=>r.GetProductionRoutePieceTypesAsync(c);public Task<ProductionRoutesConfigDto> UpsertProductionRoutesConfigAsync(ProductionRoutesConfigDto config,CancellationToken c)=>r.UpsertProductionRoutesConfigAsync(config,c);public Task<bool> UpdateCurrencySettingsAsync(string currencyName,string preferredCurrency,CancellationToken c){var code=preferredCurrency.Trim().ToUpperInvariant();if(!SupportedCurrencies.TryGetValue(code,out var supportedName))throw new ArgumentException("العملة المحددة غير مدعومة للعرض.");var name=currencyName.Trim();if(!string.Equals(name,supportedName,StringComparison.Ordinal)&&!(code=="YER"&&name=="ريال"))throw new ArgumentException("اسم العملة لا يطابق الكود المحدد.");return r.UpdateCurrencySettingsAsync(name,code,c);}public Task<bool> UpdatePrintSettingsAsync(IReadOnlyDictionary<string,string> values,CancellationToken c){var normalized=PrintSettingsValidator.NormalizeAndValidate(values);return r.UpdatePrintSettingsAsync(normalized,c);}}